import{_ as t,o as a,c as o,a0 as r}from"./chunks/framework.BQGW-Zpy.js";const m=JSON.parse('{"title":"How It Works","description":"","frontmatter":{},"headers":[],"relativePath":"get-started/how-it-works.md","filePath":"get-started/how-it-works.md"}'),n={name:"get-started/how-it-works.md"};function i(s,e,h,c,l,d){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="how-it-works" tabindex="-1">How It Works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How It Works&quot;">​</a></h1><h2 id="the-five-step-flow" tabindex="-1">The five-step flow <a class="header-anchor" href="#the-five-step-flow" aria-label="Permalink to &quot;The five-step flow&quot;">​</a></h2><ol><li><strong>Sender pays in fiat.</strong> Card or SEPA transfer, through a licensed PSP sandbox. No wallet, no address, no crypto knowledge required.</li><li><strong>The PSP confirms via webhook.</strong> Our backend receives a verified payment-confirmed event.</li><li><strong>Routing decision.</strong> <a href="./../reference/modules.html#corridorroutermjs"><code>chooseSettlementRail</code></a> picks a settlement chain. Hedera by default, falling back only when the destination partner requires a different chain or the amount exceeds Hedera&#39;s real, checked liquidity depth.</li><li><strong>Settlement + anchoring.</strong> The compliance check, the quoted FX rate, and the routing decision itself are each hashed and anchored to a Hedera Consensus Service (HCS) topic with a consensus timestamp neither party controls.</li><li><strong>Payout.</strong> The licensed destination partner converts to local currency and credits an ordinary bank account. The recipient never knows a blockchain was involved.</li><li><strong>Completion anchor.</strong> A fourth record, &quot;this transfer is fully complete&quot;, is anchored only once <strong>both</strong> the source-side and destination-side partner have independently signed off through the Hedera Schedule Service, see <a href="./../architecture/trust-layer.html#the-completion-anchor-gated-by-two-parties-not-one">The Trust Layer</a>. This is genuine two-party confirmation, not our backend marking its own homework.</li></ol><h2 id="why-anchor-the-routing-decision-not-just-compliance" tabindex="-1">Why anchor the <em>routing decision</em>, not just compliance? <a class="header-anchor" href="#why-anchor-the-routing-decision-not-just-compliance" aria-label="Permalink to &quot;Why anchor the *routing decision*, not just compliance?&quot;">​</a></h2><p>Anyone can ask &quot;why did my transfer settle on Ethereum instead of Hedera?&quot; Because the decision and its stated reason are anchored, the answer is independently verifiable, not just something we assert after the fact.</p><h2 id="what-verifiable-actually-means-here" tabindex="-1">What &quot;verifiable&quot; actually means here <a class="header-anchor" href="#what-verifiable-actually-means-here" aria-label="Permalink to &quot;What &quot;verifiable&quot; actually means here&quot;">​</a></h2><p>At any point, a third party, a regulator, an auditor, a curious teammate, can:</p><ol><li>Take the compliance/quote/routing record as it exists right now</li><li>Recompute its SHA-256 hash</li><li>Fetch the anchored hash from a <strong>public Hedera Mirror Node</strong>, not our API, not our database</li><li>Compare the two</li></ol><p>If they match, the record has not changed since it was anchored. If someone edited it, even us, the hashes diverge and the mismatch is immediate and undeniable. This is demonstrated live in <a href="./running-the-demo.html">Running the Demo</a>.</p>',9)])])}const f=t(n,[["render",i]]);export{m as __pageData,f as default};
